using System;using System.Collections.Generic;public class MedianMaintenance{private readonly PriorityQueue<int, int> maxHeap=new PriorityQueue<int,int>(Comparer<int>.Create((x,y)=>y.CompareTo(x)));private readonly PriorityQueue<int, int> minHeap=new PriorityQueue<int,int>();public void Insert(int number){if(maxHeap.Count==0||number<=maxHeap.Peek()){maxHeap.Enqueue(number,number);}else{minHeap.Enqueue(number,number);}BalanceHeaps();}public double GetMedian(){if(maxHeap.Count>minHeap.Count){return maxHeap.Peek();}return (maxHeap.Peek()+minHeap.Peek())/2.0;}private void BalanceHeaps(){if(maxHeap.Count>minHeap.Count+1){minHeap.Enqueue(maxHeap.Dequeue(),maxHeap.Dequeue());}else if(minHeap.Count>maxHeap.Count){maxHeap.Enqueue(minHeap.Dequeue(),minHeap.Dequeue());}}}